def normalize_path(path: str) -> str:
    if not path:
        return '.'
    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
        else:
            stack.append(part)

    result = '/'.join(stack)
    if is_absolute:
        return '/' + result
    return result if result else '.'

def extract_components(path: str) -> dict:
    last_slash = path.rfind('/')
    if last_slash == -1:
        dir_part = '.'
        base = path
    else:
        dir_part = path[:last_slash] if last_slash > 0 else '/'
        base = path[last_slash + 1:]

    last_dot = base.rfind('.')
    if last_dot > 0:
        name = base[:last_dot]
        ext = base[last_dot:]
    else:
        name = base
        ext = ''

    return {'dir': dir_part, 'base': base, 'name': name, 'ext': ext}

def resolve_paths(base_path: str, relative_path: str) -> str:
    if relative_path.startswith('/'):
        return normalize_path(relative_path)
    combined = base_path + '/' + relative_path
    return normalize_path(combined)

