function normalizePath(path) {
  if (!path) return '.';
  const isAbsolute = path.startsWith('/');
  const parts = path.split('/');
  const stack = [];

  for (const part of parts) {
    if (part === '' || part === '.') continue;
    if (part === '..') {
      if (stack.length && stack[stack.length - 1] !== '..') stack.pop();
    } else {
      stack.push(part);
    }
  }

  const result = stack.join('/');
  if (isAbsolute) return '/' + result;
  return result || '.';
}

function extractComponents(path) {
  const lastSlash = path.lastIndexOf('/');
  const dir = lastSlash <= 0 ? (lastSlash === 0 ? '/' : '.') : path.slice(0, lastSlash);
  const base = path.slice(lastSlash + 1);
  const lastDot = base.lastIndexOf('.');
  const name = lastDot > 0 ? base.slice(0, lastDot) : base;
  const ext = lastDot > 0 ? base.slice(lastDot) : '';
  return { dir, base, name, ext };
}

function resolvePaths(basePath, relativePath) {
  if (relativePath.startsWith('/')) return normalizePath(relativePath);
  return normalizePath(basePath + '/' + relativePath);
}
